{"actions":[{"type":"search_files","reason":"Inspect visible workspace to identify any existing VM/QEMU setup files or scripts before making changes.","args":{"pattern":"**/*","path":"/app","max_results":200}},{"type":"success_contract","reason":"Define measurable completion criteria from the original request and visible environment before implementation.","args":{"objective":"Run Windows 3.11 for Workgroups from /app/isos/win311.img in QEMU with immutable snapshot mode, VNC on :1 (port 5901), nginx web access on port 80, and programmatic keyboard input support, leaving the VM running in the background at the Windows 3.11 desktop.","required_artifacts":["A running QEMU process launched against /app/isos/win311.img","A VNC listener on 127.0.0.1:5901 or equivalent :1 binding","An nginx listener on port 80 serving a web interface for remote access","A QEMU launch configuration or wrapper that enables snapshot mode and programmatic keyboard input"],"required_behaviors":["QEMU starts successfully and remains running in the background","The VM reaches the Windows 3.11 desktop state","VNC display :1 is accessible for monitoring","QEMU is configured so keyboard input can be injected programmatically beyond manual VNC interaction","The base disk image is not modified because QEMU runs in snapshot mode"],"known_invalid_patterns":["File existence without a running VM","A QEMU command that does not actually start or remain running","VNC or nginx configuration that is present but not listening","Manual-only keyboard control without a programmatic input path","Checks that only prove binaries exist or commands parse"],"verification_plan":["Inspect workspace for existing launch scripts or configs","Start or adapt QEMU with snapshot mode, VNC :1, and a keyboard-control channel","Start nginx on port 80 with a simple web interface if needed","Probe listeners and process state","Use QEMU monitor or another external control path to demonstrate programmatic keyboard input capability","Confirm the VM is at the Windows 3.11 desktop via VNC or logs"],"finalization_evidence_required":["Receipt-backed evidence of the QEMU launch command and running process","Receipt-backed evidence of VNC listening on port 5901","Receipt-backed evidence of nginx listening on port 80","Receipt-backed evidence of a programmatic keyboard input path being configured or exercised","Receipt-backed evidence that the VM reached the Windows 3.11 desktop or equivalent boot-complete state"]}},{"type":"plan_update","reason":"Track the implementation and verification sequence for the VM bring-up task.","args":{"objective":"Bring up Windows 3.11 in QEMU from /app/isos/win311.img with snapshot mode, VNC :1, nginx on port 80, and programmatic keyboard control, then verify it is running in the background at the desktop.","current_focus":"Inspect workspace and existing artifacts, then create or adapt a launch wrapper/config if none exists.","implementation_approach":["Search for any existing QEMU/nginx scripts or configs in /app","If absent, create a minimal launcher that starts nginx and QEMU with snapshot mode, VNC :1, and a monitor/control socket suitable for scripted keyboard input","Use a background launch method that preserves the VM after the command returns","Verify listeners, process state, and keyboard-control path with targeted probes"],"validation_strategy":["Check that port 5901 is listening for VNC","Check that port 80 is listening for nginx","Check that QEMU is running with the intended arguments","Exercise or inspect the QEMU monitor/control channel for keyboard injection capability","Confirm boot progress to the Windows 3.11 desktop using visible runtime evidence"],"known_bad_behavior":["Launching without snapshot mode","No external control path for keyboard injection","Only manual VNC interaction available","No persistent background process","Listener checks without actual service readiness"],"evidence_gaps":["Need to discover whether any existing launcher/config already exists","Need runtime evidence of QEMU and nginx readiness","Need evidence of desktop state"],"risks":["QEMU 5.2.0 compatibility constraints","Missing helper tools may require using shell builtins or available utilities","Windows 3.11 boot timing may require patience and log inspection"],"next_steps":["Inspect visible files and any receipts","Implement or adapt launcher if needed","Run the launcher and probe services"],"evidence_required_before_finalize":["Running QEMU process evidence","VNC port 5901 listening evidence","nginx port 80 listening evidence","Programmatic keyboard input path evidence","Desktop/boot-complete evidence"]}}]}
